// Jenkinsfile (root) — monorepo pipeline, last touched 2024-11
pipeline {
  agent { label 'linux-docker-xl' }
  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '40'))
    timeout(time: 90, unit: 'MINUTES')
  }
  environment {
    PNPM_HOME = '/opt/pnpm'
    TURBO_TELEMETRY_DISABLED = '1'
    REGISTRY = 'registry.internal.corp:5000'
  }
  stages {
    stage('Install') {
      steps {
        sh 'pnpm install --frozen-lockfile'
      }
    }
    stage('Lint') {
      steps {
        sh 'pnpm run lint --filter="[origin/main...HEAD]"'
      }
    }
    stage('Build auth') {
      steps {
        sh 'pnpm --filter packages/auth run build'
        sh 'pnpm --filter packages/auth run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/auth/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build billing') {
      steps {
        sh 'pnpm --filter packages/billing run build'
        sh 'pnpm --filter packages/billing run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/billing/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build catalog') {
      steps {
        sh 'pnpm --filter packages/catalog run build'
        sh 'pnpm --filter packages/catalog run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/catalog/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build checkout') {
      steps {
        sh 'pnpm --filter packages/checkout run build'
        sh 'pnpm --filter packages/checkout run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/checkout/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build notifications') {
      steps {
        sh 'pnpm --filter packages/notifications run build'
        sh 'pnpm --filter packages/notifications run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/notifications/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build search') {
      steps {
        sh 'pnpm --filter packages/search run build'
        sh 'pnpm --filter packages/search run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/search/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build gateway') {
      steps {
        sh 'pnpm --filter packages/gateway run build'
        sh 'pnpm --filter packages/gateway run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/gateway/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build admin-ui') {
      steps {
        sh 'pnpm --filter packages/admin-ui run build'
        sh 'pnpm --filter packages/admin-ui run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/admin-ui/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build web-app') {
      steps {
        sh 'pnpm --filter packages/web-app run build'
        sh 'pnpm --filter packages/web-app run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/web-app/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build shared-utils') {
      steps {
        sh 'pnpm --filter packages/shared-utils run build'
        sh 'pnpm --filter packages/shared-utils run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/shared-utils/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build i18n') {
      steps {
        sh 'pnpm --filter packages/i18n run build'
        sh 'pnpm --filter packages/i18n run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/i18n/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Build analytics') {
      steps {
        sh 'pnpm --filter packages/analytics run build'
        sh 'pnpm --filter packages/analytics run typecheck'
      }
      post { failure { archiveArtifacts artifacts: 'packages/analytics/dist/**/*.log', allowEmptyArchive: true } }
    }
    stage('Test (sharded)') {
      parallel {
        stage('shard-1') { steps { sh './scripts/run-tests.sh --shard 1/4' } }
        stage('shard-2') { steps { sh './scripts/run-tests.sh --shard 2/4' } }
        stage('shard-3') { steps { sh './scripts/run-tests.sh --shard 3/4' } }
        stage('shard-4') { steps { sh './scripts/run-tests.sh --shard 4/4' } }
      }
    }
    stage('Docker build') {
      when { branch 'main' }
      steps {
        sh 'docker build -t $REGISTRY/monorepo/gateway:$GIT_COMMIT -f docker/gateway.Dockerfile .'
        sh 'docker build -t $REGISTRY/monorepo/web-app:$GIT_COMMIT -f docker/web-app.Dockerfile .'
        sh 'docker push $REGISTRY/monorepo/gateway:$GIT_COMMIT'
        sh 'docker push $REGISTRY/monorepo/web-app:$GIT_COMMIT'
      }
    }
    stage('Deploy staging') {
      when { branch 'main' }
      steps {
        withCredentials([file(credentialsId: 'kubeconfig-staging', variable: 'KUBECONFIG')]) {
          sh './scripts/deploy.sh staging $GIT_COMMIT'
        }
      }
    }
    stage('Deploy production') {
      when { branch 'main' }
      steps {
        input message: 'Deploy to production?', ok: 'Ship it'
        withCredentials([file(credentialsId: 'kubeconfig-prod', variable: 'KUBECONFIG')]) {
          sh './scripts/deploy.sh production $GIT_COMMIT'
        }
      }
    }
  }
  post {
    always { junit 'reports/junit/**/*.xml' }
    failure { slackSend channel: '#ci-alerts', message: "Build failed: ${env.BUILD_URL}" }
  }
}

